SELECT 'REAL_SERVICE_UPDATE_AND_READ' AS check_name, 1 / CASE WHEN (NOT (current_setting('debate_dml_probe.updated')::jsonb ? 'error') AND current_setting('debate_dml_probe.updated')::jsonb->>'revision'='2' AND public.debate_v3_read('de-69ddcb067b431a666ff395d98d00473d')->>'revision'='2' AND public.debate_v3_read('de-69ddcb067b431a666ff395d98d00473d')->>'title'='Synthetic DML rollback-only update') THEN 1 ELSE 0 END AS passed;

SELECT 'ACTOR_LIST_ISOLATION' AS check_name, 1 / CASE WHEN (jsonb_array_length(public.debate_v3_list('10000000-0000-4000-8000-000000009909'))=1 AND public.debate_v3_list('10000000-0000-4000-8000-000000009908')='[]'::jsonb) THEN 1 ELSE 0 END AS passed;

SELECT 'EXACT_APPEND_AUDIT' AS check_name, 1 / CASE WHEN ((SELECT count(*) FROM public.debate_v3_audit WHERE event_id='de-69ddcb067b431a666ff395d98d00473d' AND actor_id='10000000-0000-4000-8000-000000009909')=2 AND (SELECT count(*) FROM public.debate_v3_receipts WHERE event_id='de-69ddcb067b431a666ff395d98d00473d' AND actor_id='10000000-0000-4000-8000-000000009909')=2) THEN 1 ELSE 0 END AS passed;

-- This inert outbox row is a SQL fixture, not a service-generated delivery or provider call.

INSERT INTO public.debate_v3_outbox(id,event_id,actor_id,type,job,next_attempt_ms) VALUES('de-69ddcb067b431a666ff395d98d00473d:rollback-only-job','de-69ddcb067b431a666ff395d98d00473d','10000000-0000-4000-8000-000000009909','synthetic_probe','{"id":"de-69ddcb067b431a666ff395d98d00473d:rollback-only-job","eventId":"de-69ddcb067b431a666ff395d98d00473d","actorId":"10000000-0000-4000-8000-000000009909","type":"synthetic_probe","createdAt":1800000000000,"payload":{"rollbackOnly":true}}'::jsonb,1800000000000);

SELECT set_config('debate_dml_probe.first_claim', (public.debate_v3_claim_jobs('de-69ddcb067b431a666ff395d98d00473d',1,1800000000000))::text, true);

SELECT 'FIRST_JOB_CLAIM' AS check_name, 1 / CASE WHEN (jsonb_array_length(current_setting('debate_dml_probe.first_claim')::jsonb)=1 AND current_setting('debate_dml_probe.first_claim')::jsonb->0->>'id'='de-69ddcb067b431a666ff395d98d00473d:rollback-only-job' AND current_setting('debate_dml_probe.first_claim')::jsonb->0->>'attempts'='1' AND length(current_setting('debate_dml_probe.first_claim')::jsonb->0->>'claimId')=36) THEN 1 ELSE 0 END AS passed;

SELECT set_config('debate_dml_probe.active_claim', (public.debate_v3_claim_jobs('de-69ddcb067b431a666ff395d98d00473d',1,1800000000001))::text, true);

SELECT 'ACTIVE_JOB_LEASE_NOT_RECLAIMED' AS check_name, 1 / CASE WHEN (current_setting('debate_dml_probe.active_claim')::jsonb='[]'::jsonb) THEN 1 ELSE 0 END AS passed;

SELECT set_config('debate_dml_probe.second_claim', (public.debate_v3_claim_jobs('de-69ddcb067b431a666ff395d98d00473d',1,1800000060001))::text, true);

SELECT 'EXPIRED_JOB_RECLAIMED' AS check_name, 1 / CASE WHEN (jsonb_array_length(current_setting('debate_dml_probe.second_claim')::jsonb)=1 AND current_setting('debate_dml_probe.second_claim')::jsonb->0->>'attempts'='2' AND current_setting('debate_dml_probe.second_claim')::jsonb->0->>'claimId'<>current_setting('debate_dml_probe.first_claim')::jsonb->0->>'claimId') THEN 1 ELSE 0 END AS passed;

SELECT set_config('debate_dml_probe.rejected', (public.debate_v3_finish_job(jsonb_build_object('jobId','de-69ddcb067b431a666ff395d98d00473d:rollback-only-job','claimId',current_setting('debate_dml_probe.first_claim')::jsonb->0->>'claimId','status','completed','now',1800000060002,'result',jsonb_build_object('synthetic',true))))::text, true);

