SELECT set_config('debate_dml_probe.finished', (public.debate_v3_finish_job(jsonb_build_object('jobId','de-69ddcb067b431a666ff395d98d00473d:rollback-only-job','claimId',current_setting('debate_dml_probe.second_claim')::jsonb->0->>'claimId','status','completed','now',1800000060003,'result',jsonb_build_object('synthetic',true))))::text, true);

