SELECT 'STUDY_CATALOG_V1_V2_READ_PARITY' AS check_name, 1 / CASE WHEN (public.study_room_catalog_v1() IS NOT DISTINCT FROM public.study_room_catalog_v2()) THEN 1 ELSE 0 END AS passed;

DELETE FROM public.debate_v3_outbox WHERE id='de-69ddcb067b431a666ff395d98d00473d:rollback-only-job' AND event_id='de-69ddcb067b431a666ff395d98d00473d' AND actor_id='10000000-0000-4000-8000-000000009909';

