SELECT 'SCOPED_DELETE_COMPLETES' AS check_name, 1 / CASE WHEN (public.debate_v3_read('de-69ddcb067b431a666ff395d98d00473d') IS NULL AND NOT EXISTS(SELECT 1 FROM public.debate_v3_receipts WHERE event_id='de-69ddcb067b431a666ff395d98d00473d') AND NOT EXISTS(SELECT 1 FROM public.debate_v3_audit WHERE event_id='de-69ddcb067b431a666ff395d98d00473d') AND public.debate_v3_read_job('de-69ddcb067b431a666ff395d98d00473d:rollback-only-job') IS NULL) THEN 1 ELSE 0 END AS passed;

