SET LOCAL ROLE postgres;

SELECT 'UNCHANGED_CATALOG' AS check_name, 1 / CASE WHEN ((SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key),'[]'::jsonb)::text) FROM private.study_room_catalog c)=current_setting('debate_dml_probe.catalog_before')) THEN 1 ELSE 0 END AS passed;

SELECT 'UNCHANGED_CATALOG_AUDIT' AS check_name, 1 / CASE WHEN ((SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key,revision),'[]'::jsonb)::text) FROM private.study_room_catalog_audit c)=current_setting('debate_dml_probe.catalog_audit_before')) THEN 1 ELSE 0 END AS passed;

SELECT 'UNCHANGED_LEDGER' AS check_name, 1 / CASE WHEN ((SELECT md5(coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]'::jsonb)::text) FROM supabase_migrations.schema_migrations)=current_setting('debate_dml_probe.ledger_before')) THEN 1 ELSE 0 END AS passed;

SELECT 'UNCHANGED_ADMISSIONS' AS check_name, 1 / CASE WHEN ((SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY request_id),'[]'::jsonb)::text) FROM private.study_room_admissions c)=current_setting('debate_dml_probe.admissions_before')) THEN 1 ELSE 0 END AS passed;

SELECT 'UNCHANGED_ADMISSION_COMMANDS' AS check_name, 1 / CASE WHEN ((SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY actor_user_id,command_id),'[]'::jsonb)::text) FROM private.study_room_admission_commands c)=current_setting('debate_dml_probe.admission_commands_before')) THEN 1 ELSE 0 END AS passed;

SELECT jsonb_build_object('checkpoint','DML_CHECKS_PASSED_ROLLBACK_PENDING','rollbackPending',true,'authAccountsCreated',0,'providerCalls',0,'actualPermissionErrorProbes',false,'nativeConcurrentConnections',false) AS rollback_probe;

