SELECT jsonb_build_object('checkpoint','DML_ROLLBACK_ROWS_ABSENT','targetProjectMustBeVerifiedExternally','hbllomlijfznnuudpdvr','eventId','de-69ddcb067b431a666ff395d98d00473d','actorId','10000000-0000-4000-8000-000000009909','providerCalls',0,'actualPermissionErrorProbes',false,'nativeConcurrentConnections',false,'catalogHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key),'[]'::jsonb)::text) FROM private.study_room_catalog c),'catalog_auditHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY room_key,revision),'[]'::jsonb)::text) FROM private.study_room_catalog_audit c),'ledgerHash',(SELECT md5(coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]'::jsonb)::text) FROM supabase_migrations.schema_migrations),'admissionsHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY request_id),'[]'::jsonb)::text) FROM private.study_room_admissions c),'admission_commandsHash',(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY actor_user_id,command_id),'[]'::jsonb)::text) FROM private.study_room_admission_commands c),'debateFunctionCount',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'debate_v3_%')) AS rollback_probe;
